<?php
require_once __DIR__.'/_layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['booking_id']??0);$status=$_POST['status']??'';if(in_array($status,['pending','confirmed','cancelled'],true)){$s=$pdo->prepare('UPDATE bookings SET status=? WHERE booking_id=?');$s->execute([$status,$id]);flash('success','Reservation status updated.');}redirect('bookings.php');}$search=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT b.*,r.room_name FROM bookings b JOIN rooms r ON b.room_id=r.room_id WHERE (b.guest_name LIKE ? OR b.guest_email LIKE ? OR b.booking_reference LIKE ?)';$args=["%$search%","%$search%","%$search%"];$valid=['pending','confirmed','cancelled'];if(in_array($status,$valid,true)){$sql.=' AND b.status=?';$args[]=$status;}$sql.=' ORDER BY b.created_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();admin_start('Booking management');?><form class="filter-bar" method="get"><div class="form-field"><label>Find a reservation</label><input name="q" value="<?= e($search) ?>" placeholder="Name, email or reference"></div><div class="form-field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach($valid as $v): ?><option <?= $status===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><button class="button">Search</button></form><div style="overflow:auto"><table class="data-table"><thead><tr><th>Reference</th><th>Guest details</th><th>Room</th><th>Dates</th><th>Party</th><th>Total</th><th>Status / update</th></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td><?= e($b['booking_reference']) ?></td><td><?= e($b['guest_name']) ?><br><?= e($b['guest_email']) ?><br><?= e($b['guest_phone']) ?></td><td><?= e($b['room_name']) ?></td><td><?= e($b['check_in']) ?><br><?= e($b['check_out']) ?></td><td><?= (int)$b['guests'] ?></td><td>₹<?= number_format((float)$b['total_amount']) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="booking_id" value="<?= (int)$b['booking_id'] ?>"><select name="status"><?php foreach($valid as $v): ?><option value="<?= $v ?>" <?= $b['status']===$v?'selected':'' ?>><?= ucfirst($v) ?></option><?php endforeach; ?></select><button class="button button-small">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php admin_end(); ?>
